; Reset the play state. Called by restart_to_title, start_attract_demo, start_new_game and next_turn_enter_room
; (new fall or the other player's turn).
; - Clears enemy_follow_x of Yamo and the Ninja (no enemy follows Bruce into the next room).
; - init_game_irq (game raster IRQ, CIA interrupts off), init_keyboard; last_game_key = $FF.
; - Builds the text row address tables (text_line_top_lo/hi, text_line_bottom_lo/hi) for double rows from
;   screen row -1, then makes entry 0 the single status row 0 and sends the lower rows of entries 0 and 1 to
;   io1_dummy.
; - Prepares the game screen: colour RAM $F8 (multicolour, black), rows 0-1 black with spaces, row 2 of
;   character 6 (separator), all eight sprite pointers to block $0F, sprite_buf_a_spr0-sprite_buf_b_spr4
;   ($8180-$83FF) cleared, border/background colours from vic_start_colours, VIC bank 2, screen game_screen
;   with charset_rooms_0_9, multicolour text, sprites off and X-expanded.
; - Draws the status line (score, TOP, the blinking player label, FALLS) and sets anim_chars_delay and
;   anim_chars_step_count to 1 and all sprite_owner slots free.
; - Tail-jumps to spawn_actor with X = 0, A = 0: spawns Bruce.
reset_play_state
        lda #$00
        sta enemy_follow_x              ; no carried-over Yamo/Ninja position
        sta enemy_follow_x+1
        jsr init_game_irq               ; irq_vector = irq_game_bottom, raster IRQ at line 251
        jsr init_keyboard               ; keyboard state and CIA port directions
        lda #$ff                        ; last_game_key = $FF: none
        sta last_game_key
        ldy #>(game_screen-$28)         ; first row address = $8BD8 = screen - 40
        lda #<(game_screen-$28)
        jsr build_screen_row_tables
; Fix the first entries: the upper row of entry 0 is screen row 0 (the status line), the lower rows of
; entries 0 and 1 are io1_dummy (writes there are lost), so the separator row 2 stays intact.
        lda #$00
        sta text_line_top_lo
        sta text_line_bottom_lo
        sta text_line_bottom_lo+1
        lda #>game_screen
        sta text_line_top_hi
        lda #>io1_dummy
        sta text_line_bottom_hi
        sta text_line_bottom_hi+1
        jsr clear_text_screen           ; clear the text rows
        lda #$f8                        ; colour RAM = $F8: multicolour characters, colour 0
        jsr fill_colour_ram
        ldx #$27
reset_play_clear_top_rows
        lda #$00
        sta $d800,x                     ; colour RAM rows 0 and 1 black
        sta $d828,x
        lda #$20                        ; row 0 (status line): spaces
        sta game_screen,x
        lda #$06                        ; row 2: character 6 (separator line)
        sta game_screen+80,x
        cpx #$08                        ; only X = 0-7: sprite pointers and the solid block
        bcs reset_play_next_column
        lda #(sprite_buf_b_spr4 & $3fff) / 64
        sta sprite_pointers,x           ; all eight sprite pointers = block $0F
        lda #$ff
        sta text_font_letters,x         ; character 32 of the text font = solid block (as patched by cold_start)
reset_play_next_column
        dex
        bpl reset_play_clear_top_rows
        lda #$00
        tax
reset_play_clear_sprite_data
        sta sprite_buf_a_spr0,x         ; clear sprite blocks 6-15 ($8180-$83FF)
        sta sprite_buf_a_spr4,x
        sta sprite_buf_b_spr1,x
        inx
        bne reset_play_clear_sprite_data
        ldx #$03
reset_play_set_colours
        lda vic_start_colours,x         ; $D020-$D023 = black, dark grey, white, light blue
        sta EXTCOL,x
        dex
        bpl reset_play_set_colours
        lda #$01                        ; VIC bank 2 ($8000-$BFFF)
        sta CI2PRA                      ; $dd00: vicBank 2, vicAddresses $8000-$bfff
        lda #$38                        ; VMCSB $38: screen game_screen ($8C00), charset_rooms_0_9 ($A000); room_vmcsb is the value irq_game_playfield uses
        sta VMCSB                       ; $d018: screenOffset $0c00, characterOffset $2000, bitmapOffset $2000
        sta room_vmcsb
        lda #$18                        ; multicolour characters, 40 columns
        sta SCROLX                      ; $d016: xScroll 0, columns 40, multicolorMode
        lda #$00
        sta SPENA                       ; $d015: sprites 
        sta YXPAND
        sta SPBGPR
        sta SPMC
        lda #$ff                        ; all sprites X-expanded
        sta XXPAND                      ; $d01d: sprites 0,1,2,3,4,5,6,7
        lda #$80                        ; status line: score and TOP (show_score and show_high_score do not use A)
        jsr show_score
        jsr show_high_score
        lda #$11                        ; up_blink_timer = $11
        sta up_blink_timer
        jsr blink_player_label
        jsr print_top_label
        jsr print_falls_label
        jsr show_falls_count
        lda #$01                        ; anim_chars_delay = anim_chars_step_count = 1
        sta anim_chars_delay
        sta anim_chars_step_count
        ldx #$04
        lda #$ff
reset_play_clear_sprite_owners
        sta sprite_owner,x              ; all five sprite slots free
        dex
        bpl reset_play_clear_sprite_owners
        ldx #$00                        ; X = 0 actor Bruce, A = 0 type Bruce
        lda #$00
        jmp spawn_actor
; Set up the game interrupts: disable and acknowledge all CIA interrupts, set irq_vector to irq_game_bottom,
; enable the VIC raster IRQ at line 251 (below the play area; that handler starts the chain of the frame)
; and start SID voice 3 noise again (random source). Called by reset_play_state. Changes A.
init_game_irq
        lda #$7f
        sta CI2ICR                      ; $dd0d: line NMI
        sta CIAICR
        lda CI2ICR
        lda CIAICR
        cld
        lda #<irq_game_bottom           ; irq_vector = irq_game_bottom
        sta irq_vector
        lda #>irq_game_bottom
        sta irq_vector_hi
        lda #$01                        ; raster interrupt only
init_game_irq_enable
        sta IRQMSK                      ; $d01a: sources raster
        sta VICIRQ
        lda SCROLY
        and #$7f                        ; raster compare bit 8 = 0
        sta SCROLY
        lda #$fb                        ; raster line 251
        sta RASTER
        lda #$ff                        ; voice 3: frequency $FFFF, noise waveform: RANDOM gives random bytes
        sta FRELO3
        sta FREHI3
        lda #$80
        sta VCREG3
        rts
; Build the text row address tables of print_message and the room code.
; Input: A/Y = low/high byte of the first address. Entry i (0-13) of text_line_top_lo/hi = first + 80*i;
; entry i of text_line_bottom_lo/hi = first + 40 + 80*i. reset_play_state passes game_screen - 40, so
; entry i is the double row of screen rows 2i-1 (upper) and 2i (lower). Changes A, X.
build_screen_row_tables
        ldx #$00
        sta text_line_top_lo
        sty text_line_top_hi
build_row_tables_top_loop
        lda text_line_top_lo,x
        clc
        adc #$50                        ; +80: two screen rows
        sta text_line_top_lo+1,x
        lda text_line_top_hi,x
        adc #$00
        sta text_line_top_hi+1,x
        inx
        cpx #$0d                        ; 13 more entries: 14 in all
        bcc build_row_tables_top_loop
        lda text_line_top_lo
        clc
        adc #$28                        ; bottom row = top row + 40
        sta text_line_bottom_lo
        lda text_line_top_hi
        adc #$00
        sta text_line_bottom_hi
        ldx #$00
build_row_tables_bottom_loop
        lda text_line_bottom_lo,x
        clc
        adc #$50
        sta text_line_bottom_lo+1,x
        lda text_line_bottom_hi,x
        adc #$00
        sta text_line_bottom_hi+1,x
        inx
        cpx #$0d
        bcc build_row_tables_bottom_loop
        rts
